import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_tanh_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Fast approximate tanh using hardware-accelerated __expf intrinsic.
// This trades a small amount of precision for significantly reduced
// instruction count compared to the standard tanhf implementation,
// which is beneficial for this purely memory/compute-bound elementwise op.
__device__ __forceinline__ float fast_tanhf(float x) {
    float ax = fabsf(x);
    float e  = __expf(-2.0f * ax);
    float t  = (1.0f - e) / (1.0f + e);
    return copysignf(t, x);
}
// Vectorized tanh kernel using CuTe tensors over float4-packed data.
// Vectorized tanh kernel over float4-packed data using a single
// grid-stride loop. Removing the manual 4x thread-level unrolling
// reduces per-thread register pressure, allowing more warps to be
// resident concurrently and letting the hardware scheduler hide
// memory latency more effectively for this memory-bound elementwise op.
__global__ void tanh_vec4_kernel(
    const float4* __restrict__ X,
    float4* __restrict__ Y,
    int64_t N4)
{
  int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * gridDim.x;
  for (int64_t i = idx; i < N4; i += stride) {
    // Use __ldg to route the read-only input through the texture/read-only
    // cache path, which improves effective bandwidth for this streaming,
    // memory-bound elementwise workload since X is never written to.
    float4 v = __ldg(&X[i]);
    v.x = fast_tanhf(v.x);
    v.y = fast_tanhf(v.y);
    v.z = fast_tanhf(v.z);
    v.w = fast_tanhf(v.w);
    Y[i] = v;
  }
}
// Scalar tail kernel for remaining elements that don't fit into a float4 group.
__global__ void tanh_scalar_kernel(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int64_t offset,
    int64_t N)
{
  Tensor mX = make_tensor(make_gmem_ptr(X + offset), make_shape(N - offset));
  Tensor mY = make_tensor(make_gmem_ptr(Y + offset), make_shape(N - offset));
  int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * gridDim.x;
  int64_t M = N - offset;
  for (int64_t i = idx; i < M; i += stride) {
    mY(i) = fast_tanhf(__ldg(&mX(i)));
  }
}
torch::Tensor cute_tanh_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
  TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
  auto y = torch::empty_like(x);
  int64_t N = x.numel();
  const float* x_ptr = x.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();
  bool aligned = (reinterpret_cast<uintptr_t>(x_ptr) % 16 == 0) &&
                 (reinterpret_cast<uintptr_t>(y_ptr) % 16 == 0);
  int64_t N4 = aligned ? (N / 4) : 0;
  int64_t rem_offset = N4 * 4;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (N4 > 0) {
    const float4* x4 = reinterpret_cast<const float4*>(x_ptr);
    float4* y4 = reinterpret_cast<float4*>(y_ptr);
    int threads = 256;
    int64_t blocks64 = (N4 + threads - 1) / threads;
    // Cache the occupancy-based block count across calls. Querying the
    // device attributes and occupancy API on every single forward call
    // adds unnecessary host-side/driver overhead for this frequently
    // invoked, launch-bound elementwise op. Since the kernel and thread
    // configuration are fixed, the optimal occupancy-derived block count
    // never changes, so we compute it only once and reuse it thereafter.
    static int64_t occupancy_blocks = 0;
    if (occupancy_blocks == 0) {
      int device = 0;
      cudaGetDevice(&device);
      int num_sms = 1;
      cudaDeviceGetAttribute(&num_sms, cudaDevAttrMultiProcessorCount, device);
      int max_active_blocks_per_sm = 1;
      cudaOccupancyMaxActiveBlocksPerMultiprocessor(&max_active_blocks_per_sm, tanh_vec4_kernel, threads, 0);
      int64_t computed = (int64_t)num_sms * (int64_t)max_active_blocks_per_sm;
      occupancy_blocks = (computed < 1) ? 1 : computed;
    }
    int64_t blocks64_final = blocks64 < occupancy_blocks ? blocks64 : occupancy_blocks;
    int blocks = (int)(blocks64_final < 1 ? 1 : blocks64_final);
    tanh_vec4_kernel<<<blocks, threads, 0, stream>>>(x4, y4, N4);
  }

  if (rem_offset < N) {
    int threads = 256;
    int64_t rem = N - rem_offset;
    int64_t blocks64 = (rem + threads - 1) / threads;
    int blocks = (int)(blocks64 < 65535 ? blocks64 : 65535);
    if (blocks < 1) blocks = 1;

    tanh_scalar_kernel<<<blocks, threads, 0, stream>>>(x_ptr, y_ptr, rem_offset, N);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "cute_tanh_forward launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

cute_tanh_ext = load_inline(
    name="cute_tanh_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_tanh_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom CuTe-based CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_tanh_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_tanh_forward(x)

